import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import './Navbar.css';

// Icons (Optional: if you have react-icons installed)
// import { FaPaw, FaEnvelope, FaPlus, FaSignOutAlt } from 'react-icons/fa';

const Navbar = () => {
    const { user, logout } = useAuth();
    const navigate = useNavigate();

    const handleLogout = async () => {
        try {
            await logout();
            navigate('/login');
        } catch (error) {
            console.error("Failed to logout", error);
        }
    };

    // If user is not logged in, you might not want to show the Navbar at all,
    // or show a simplified version.
    if (!user) return null;

    return (
        <nav className="navbar">
            {/* Logo */}
            <Link to="/" className="logo">
                🐾 PetPal
            </Link>

            {/* Navigation Links */}
            <div className="nav-links">
                <Link to="/" className="nav-link">
                    Home
                </Link>

                <Link to="/add-pet" className="nav-link">
                    Add Pet
                </Link>

                <Link to="/inbox" className="nav-link">
                    Messages 💬
                </Link>

                <button onClick={handleLogout} className="logout-btn">
                    Logout
                </button>
            </div>
        </nav>
    );
};

export default Navbar;
